from itertools import combinations
cells={(r,c) for r,row in enumerate([[0,8,8,0,8,8,0],[8,8,8,8,8,8,0],[0,8,8,0,8,0,0],[0,0,8,8,8,0,0]]) for c,x in enumerate(row) if x==8}
sq={(0,1),(0,2),(1,1),(1,2)}|{(0,4),(0,5),(1,4),(1,5)}
rem=cells-sq
print(len(cells),sorted(rem))
shapes={2:{(0,1),(1,0),(1,1)},3:{(0,0),(0,1),(1,1)},4:{(0,0),(1,0),(1,1)}}
placements=[]
for color,sh in shapes.items():
 for r in range(7):
  for c in range(7):
   p={(r+a,c+b) for a,b in sh}
   if p<=rem: placements.append((color,p))
solutions=[]
def rec(left, chosen):
 if not left:
  solutions.append(chosen); return
 cell=min(left)
 for color,p in placements:
  if cell in p and p<=left: rec(left-p,chosen+[(color,p)])
rec(rem,[])
print('solutions',len(solutions))
for s in solutions[:20]: print([(x,sorted(p)) for x,p in s])

